                    warnings.warn(
                        "The optimal value found for "
                        "dimension %s of parameter %s is "
                        "close to the specified lower "
                        "bound %s. Decreasing the bound and"
                        " calling fit again may find a "
                        "better value." % (dim, hyp.name, hyp.bounds[dim][0]),
                        ConvergenceWarning,
                    )
                if list_close[idx, 1]:
                    warnings.warn(
                        "The optimal value found for "
                        "dimension %s of parameter %s is "
                        "close to the specified upper "
                        "bound %s. Increasing the bound and"
                        " calling fit again may find a "
                        "better value." % (dim, hyp.name, hyp.bounds[dim][1]),
                        ConvergenceWarning,
                    )
                idx += 1

    def characteristic_length_scale(self, X=None):
        """Returns the characteristic length scale of the kernel.

        For kernels with explicit length-scale parameters, returns the
        actual length scale. For others, estimates a characteristic scale
        from the hyperparameters or kernel diagonal.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features), default=None
            Input data used for estimation when no explicit length-scale
            parameter is available.

        Returns
        -------
        length_scale : float
            The characteristic length scale of the kernel.
        """
        params = self.get_params()
        for name, value in params.items():
            if "length_scale" in name and not name.endswith("_bounds"):
                return float(np.mean(np.atleast_1d(value)))
        if X is not None:
            diag_values = self.diag(X)
            return float(np.sqrt(np.mean(np.abs(diag_values)) + 1e-12))
        return 1.0

    def smoothness_order(self):
        """Returns the smoothness order of the kernel.

        The smoothness order characterizes the mean-square differentiability
        of the GP sample paths induced by this kernel. Higher values indicate
        smoother functions. Returns np.inf for infinitely smooth kernels,
        a positive float for finite smoothness, and 0 for non-smooth kernels.

        Returns
        -------
        smoothness : float
            The smoothness order.
        """
        if self.is_stationary():
            return 2.0
        return 0.0

    def suggested_regularization(self, X):
        """Suggests a regularization value based on kernel matrix properties.

        Computes a heuristic regularization value (alpha) suitable for
        numerical stability during Cholesky decomposition of the kernel
        matrix. This is based on the kernel diagonal variance and the
        characteristic length scale.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
            Input data for computing the kernel diagnostic.

        Returns
        -------
        alpha : float
            Suggested regularization value.
        """
        K_diag = self.diag(X)
        n_samples = _num_samples(X)
        diag_range = float(np.max(K_diag) - np.min(K_diag))
        scale = self.characteristic_length_scale(X)
        return (diag_range + 1e-10) / (n_samples * scale**2 + 1.0)

